  END IF;
  IF session_user <> 'postgres' OR current_user <> 'postgres' THEN
    RAISE EXCEPTION 'p2al_s3_disable_stop: must run as postgres (session %, current %)', session_user, current_user;
  END IF;
  IF current_setting('server_version_num')::int / 10000 <> 17 THEN
    RAISE EXCEPTION 'p2al_s3_disable_stop: server major % is not 17', current_setting('server_version_num');
  END IF;
  PERFORM set_config('lock_timeout', '5s', true);
  EXECUTE v_comp INTO v_state, v_digest USING 'S3';
  IF v_state IS DISTINCT FROM 'installed' THEN RAISE EXCEPTION 'p2al_s3_disable_stop: S3 is %, not installed', v_state; END IF;
  EXECUTE v_file;
  RAISE NOTICE 'p2al_s3_disable_ok: S3 grants revoked (forward recovery; no table, row or audit record dropped). 02-S3.restore.sql restores them.';
